args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?birthDate ?label WHERE {
  VALUES ?person { dbr:Georg_Wenker dbr:Ida_Turay }
  OPTIONAL { ?person dbo:birthDate ?d1 . }
  OPTIONAL { ?person dbp:birthDate ?d2 . }
  BIND(COALESCE(?d1, ?d2) AS ?birthDate)
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
  FILTER(bound(?birthDate))
}
ORDER BY ASC(?birthDate)
LIMIT 1

